import test from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import { readFile } from 'node:fs/promises';

// Evaluate the actual worker source generated by the existing Preview builder.
const builder = await readFile(new URL('./build-integrated-preview.mjs', import.meta.url), 'utf8');
const source = builder.slice(builder.indexOf('const allow ='), builder.indexOf('await writeFile(resolve(output, "preview-readonly-sw.js")'));
const worker = vm.runInNewContext(`const commit='${"0".repeat(40)}';
const NUMBER_REVIEW_PREVIEW_BRANCH_2029='gpt/perf-unified-wave4-preview-20261018';
const previewHost='sod1820-review123-sod1820-s-projects.vercel.app';
${source}\nworker;`);
async function request(path, { method = 'POST', body, origin = 'https://linswmnnkjxvweumprav.supabase.co' } = {}) {
  let handler, response, forwarded = 0;
  vm.runInNewContext(worker, {
    self: { addEventListener: (name, fn) => { if (name === 'fetch') handler = fn; } },
    URL, Response,
    fetch: async () => { forwarded++; return new Response('{}', { status: 200 }); },
  });
  handler({ request: new Request(origin + path, { method, ...(body === undefined ? {} : { body: JSON.stringify(body) }) }), respondWith: (value) => { response = value; } });
  const result = response ? await response : null;
  return { status: result?.status || 200, forwarded, blocked: result?.headers.get('X-Preview-Write-Blocked') };
}
test('existing accounts can sign in, refresh, read identity and sign out locally', async () => {
  for (const [path, options] of [
    ['/auth/v1/token?grant_type=password', { body: { email: 'test@example.invalid', password: 'synthetic' } }],
    ['/auth/v1/token?grant_type=refresh_token', { body: { refresh_token: 'synthetic' } }],
    ['/auth/v1/user', { method: 'GET' }],
    ['/auth/v1/logout?scope=local', {}],
    ['/auth/v1/otp', { body: { email: 'test@example.invalid', create_user: false } }],
    ['/auth/v1/verify', { body: { email: 'test@example.invalid', type: 'email', token: '123456' } }],
  ]) assert.deepEqual(await request(path, options), { status: 200, forwarded: 1, blocked: null }, path);
});
test('signup, global logout, account mutation, other grants and origins stay blocked', async () => {
  for (const [path, options] of [
    ['/auth/v1/signup', {}], ['/auth/v1/recover', {}], ['/auth/v1/user', { method: 'PUT' }],
    ['/auth/v1/logout', {}], ['/auth/v1/logout?scope=global', {}],
    ['/auth/v1/token?grant_type=pkce', {}], ['/auth/v1/token?grant_type=password', { method: 'GET' }],
    ['/auth/v1/token?grant_type=password', { origin: 'https://other.supabase.co' }],
    ['/auth/v1/token?grant_type=password', { origin: 'http://linswmnnkjxvweumprav.supabase.co' }],
    ['/auth/v1/otp', { body: { email: 'test@example.invalid', create_user: true } }],
    ['/auth/v1/otp', { body: { email: 'test@example.invalid' } }],
    ['/auth/v1/verify', { body: { email: 'test@example.invalid', type: 'signup', token: '123456' } }],
    ['/auth/v1/verify', { body: { phone: 'synthetic', type: 'sms', token: '123456' } }],
  ]) assert.deepEqual(await request(path, options), { status: 403, forwarded: 0, blocked: 'true' }, path);
});
test('profile/product/storage/model writes remain blocked; governed readers still work', async () => {
  for (const [path, options] of [
    ['/rest/v1/users?id=eq.A', { method: 'PATCH', body: { display_name: 'changed' } }],
    ['/rest/v1/rpc/research_state_apply_v1', {}], ['/rest/v1/rpc/claim_daily_credit', {}],
    ['/storage/v1/object/public/example', {}], ['/functions/v1/ask-raziel', {}],
    ['/functions/v1/els-search-bridge', { body: { op: 'save' } }],
  ]) assert.equal((await request(path, options)).status, 403, path);
  assert.equal((await request('/rest/v1/rpc/fn_method_value')).status, 200);
  assert.equal((await request('/functions/v1/els-search-bridge', { body: { op: 'page' } })).forwarded, 1);
});

test('guest preference reads pass through while preference writes and foreign RPCs stay blocked', async () => {
  // This RPC validates a visitor UUID and SELECTs an existing row; it never creates one.
  const readPath = '/rest/v1/rpc/notification_prefs_guest_get_v1';
  const body = { p_visitor: '11111111-1111-4111-8111-111111111111' };
  assert.deepEqual(await request(readPath, { body }), { status: 200, forwarded: 0, blocked: undefined });
  for (const [path, options] of [
    [readPath, { body, origin: 'https://other.supabase.co' }],
    ['/rest/v1/rpc/notification_prefs_guest_save_v1', { body }],
    ['/rest/v1/notification_prefs', { method: 'POST', body }],
    ['/rest/v1/notification_prefs', { method: 'PATCH', body }],
    ['/rest/v1/notification_prefs', { method: 'DELETE' }],
    ['/rest/v1/rpc/track_visit', { body: {} }],
    ['/rest/v1/rpc/link_identity', { body: {} }],
    ['/rest/v1/rpc/ingest_event', { body: {} }],
    ['/rest/v1/rpc/public_enrichment_batch', { body: {} }],
  ]) assert.deepEqual(await request(path, options), { status: 403, forwarded: 0, blocked: 'true' }, path);
});

test('the compact SECURITY INVOKER Number opening RPC is allowed and no adjacent RPC is inferred', async () => {
  const body = { p_value: 1820, p_per_method: 12 };
  assert.deepEqual(await request('/rest/v1/rpc/fn_number_opening_projection_2029', { body }), {
    status: 200, forwarded: 0, blocked: undefined,
  });
  for (const path of [
    '/rest/v1/rpc/fn_number_opening_projection_depth_2029',
    '/rest/v1/rpc/fn_number_opening_projection_save_2029',
    '/rest/v1/rpc/fn_number_opening_projection_2029_admin',
  ]) assert.deepEqual(await request(path, { body }), {
    status: 403, forwarded: 0, blocked: 'true',
  }, path);
});

test('the generated worker never intercepts or rewrites the canonical site_flags read', async () => {
  assert.doesNotMatch(worker, /lock_number|X-SOD-Preview-Overrides/);
  assert.deepEqual(await request('/rest/v1/site_flags?select=key%2Cenabled%2Cmessage%2Cmode', { method: 'GET' }), {
    status: 200, forwarded: 0, blocked: undefined,
  });
});

test('the Preview worker still blocks every site_flags write', async () => {
  for (const method of ['POST', 'PATCH', 'DELETE']) {
    assert.deepEqual(await request('/rest/v1/site_flags', { method }), {
      status: 403, forwarded: 0, blocked: 'true',
    });
  }
});
